/* ---------- voix (homme ou femme selon le guide choisi) ---------- */
var synth = window.speechSynthesis;
var MALE = /thomas|daniel|nicolas|paul|henri|claude|jacques|guillaume|mathieu|matthieu|xavier|antoine|fr[eé]d[eé]ric|r[eé]mi|jean|gr[eé]goire|olivier|denis|male|homme/i;
var FEMALE = /am[eé]lie|audrey|marie|aur[eé]lie|julie|hortense|denise|virginie|c[eé]line|l[eé]a|chantal|sylvie|[eé]lo[iï]se|vivienne|female|femme|google fran/i;
function pickVoice(g){
  if(!synth) return null;
  var V = synth.getVoices().filter(function(v){ return /^fr/i.test(v.lang); });
  if(!V.length) return null;
  function score(v){ var s=0, n=v.name, m=MALE.test(n), f=FEMALE.test(n);
    if(g==='f'){ if(f) s+=10; if(m) s-=10; } else { if(m) s+=10; if(f) s-=10; }
    if(/fr[-_]FR/i.test(v.lang)) s+=3;
    if(/enhanced|premium|natural|neural|am[eé]lior/i.test(n)) s+=2;
    if(/compact|eloquence|grandpa|grandma|rocko|shelley|flo|reed|sandy/i.test(n)) s-=4;
    return s; }
  V.sort(function(a,b){ return score(b)-score(a); });
  return V[0];
}
function clean(t){ return t.replace(/[\u{1F300}-\u{1FAFF}☀-➿️]/gu,'').replace(/\s+/g,' ').trim(); }

/* ---------- choix du guide (gardé par élève sur l'appareil) ---------- */
