  function M(g,m,x,y,z,sx,sy,sz){ var o=new T.Mesh(g,m); o.position.set(x||0,y||0,z||0); if(sx) o.scale.set(sx,sy,sz); return o; }
  var SPH=new T.SphereGeometry(1,48,32), CYL=new T.CylinderGeometry(1,1,1,32);
