  /* buste */
  root.add(M(SPH,white,0,.36,0,.78,.9,.6));
  var ring=M(new T.TorusGeometry(.2,.06,16,48),blue,0,.98,0); ring.rotation.x=Math.PI/2; root.add(ring);
  var cv=document.createElement('canvas'); cv.width=cv.height=128; var cx=cv.getContext('2d');
  cx.fillStyle='#0a1426'; cx.beginPath(); cx.arc(64,64,62,0,7); cx.fill(); cx.strokeStyle='#5ce1ff'; cx.lineWidth=6; cx.stroke();
  cx.fillStyle='#5ce1ff'; cx.font='bold 84px Georgia,serif'; cx.textAlign='center'; cx.textBaseline='middle'; cx.fillText('π',64,70);
