  head.add(M(SPH,white,0,0,0,.52,.5,.5));
  head.add(M(SPH,dark,0,-.01,.2,.46,.34,.36));
  var eyes=[M(SPH,glow,-.16,.06,.53,.07,.095,.03),M(SPH,glow,.16,.06,.53,.07,.095,.03)]; eyes.forEach(function(e){ head.add(e); });
  var brows=[M(new T.BoxGeometry(.13,.022,.02),glow,-.16,.19,.49),M(new T.BoxGeometry(.13,.022,.02),glow,.16,.19,.49)]; brows.forEach(function(b){ head.add(b); });
  var mouthM=M(new T.BoxGeometry(.2,.03,.02),glow,0,-.12,.54); head.add(mouthM);
  var smile=M(new T.TorusGeometry(.11,.016,10,40,Math.PI*.7),glow,0,-.07,.535); smile.rotation.z=Math.PI+Math.PI*.15; head.add(smile);
  [-1,1].forEach(function(s){ var e=M(CYL,blue,s*.52,0,0,.13,.12,.13); e.rotation.z=Math.PI/2; head.add(e);
    var c=M(SPH,glow,s*.58,0,0,.035,.035,.035); head.add(c); });
  head.add(M(CYL,grey,0,.56,0,.02,.18,.02)); var bulb=M(SPH,led,0,.67,0,.06,.06,.06); head.add(bulb);
