    var el2=new T.Group(); el2.position.y=-.58; sh.add(el2); el2.add(M(SPH,grey,0,0,0,.12,.12,.12));
    el2.add(M(CYL,white,0,-.26,0,.1,.45,.1)); el2.add(M(SPH,white,0,-.55,0,.14,.14,.14));
