  function size(){ var w=el.clientWidth||96, h=el.clientHeight||111; if(w===st.w&&h===st.h) return; st.w=w; st.h=h; r.setSize(w,h,false);
    cam.aspect=w/h; if(w<80){ cam.fov=26; cam.position.set(0,1.42,3.2); cam.lookAt(0,1.38,0); } else { cam.fov=30; cam.position.set(0,1.42,4.7); cam.lookAt(0,1.22,0); } cam.updateProjectionMatrix(); }
